// Run this function in an isolated browser page after loading index.html.
async function checkSecureMcpPreview() {
  const checks = [];
  const $ = selector => document.querySelector(selector);
  const tick = () => new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
  const assert = (condition, name) => { if (!condition) throw new Error(name); checks.push(name); };
  const click = async selector => { const el = $(selector); if (!el) throw new Error(`Missing: ${selector}`); el.click(); await tick(); };
  const input = (selector, value) => { $(selector).value = value; $(selector).dispatchEvent(new Event('input', {bubbles: true})); };
  const setScenario = async value => { $('#scenario').value = value; $('#scenario').dispatchEvent(new Event('change', {bubbles: true})); await tick(); };
  const countEditable = () => document.querySelectorAll('[data-action="edit-rule"]').length;
  assert($('#global-count').textContent === '0', 'global defaults start empty');
  await click('[data-action="edit-local"][data-profile="router"]');
  assert(document.activeElement.id === 'rule-text', 'opening editor focuses the visible command input');
  assert($('#rule-text').getBoundingClientRect().bottom < $('#editor-footer').getBoundingClientRect().top, 'input is above the save footer');
  assert($('.editor-scope').getBoundingClientRect().top >= $('#content').getBoundingClientRect().top, 'client/SSH scope is initially visible');
  input('#rule-text', 'pwd'); $('#rule-form').requestSubmit(); await tick();
  assert(countEditable() === 3, 'adding a rule changes the draft');
  await click('[data-action="close-editor"]');
  assert($('#action-dialog').open, 'unsaved navigation opens a discard/save dialog');
  await click('#dialog-actions [value="cancel"]');
  assert(countEditable() === 3, 'continue editing preserves the draft');
  await click('[data-action="close-editor"]'); await click('#dialog-actions [value="discard"]');
  await click('[data-action="edit-local"][data-profile="router"]');
  assert(countEditable() === 2, 'discard restores the saved command set');
  await click('[data-action="close-editor"]');
  await click('[data-page="global"]'); await click('[data-action="fill-global"]');
  assert(countEditable() === 15 && $('#global-count').textContent === '0', 'fill adds 15 rules only to the draft');
  await click('[data-action="fill-presets"]'); assert(countEditable() === 15, 'repeated fill is idempotent');
  await click('[data-action="clear-rules"]'); await click('#dialog-actions [value="cancel"]');
  assert(countEditable() === 15, 'canceling clear retains rules');
  await click('[data-action="save-editor"]');
  assert($('#global-count').textContent === '15', 'saving publishes global rules in the preview');
  await click('[data-page="clients"]');
  assert($('.connection-meta').textContent.includes('生效 15 条'), 'effective count deduplicates local/global overlap');
  await click('[data-action="edit-local"][data-profile="router"]');
  assert(document.querySelectorAll('.global-source').length === 15, 'inherited rules display as read-only');
  let copied = '';
  const originalClipboard = Object.getOwnPropertyDescriptor(navigator, 'clipboard');
  Object.defineProperty(navigator, 'clipboard', {configurable: true, value: {writeText: async value => { copied = value; }}});
  await click('[data-action="copy-rules"]');
  assert(JSON.parse(copied).rules.length === 2, 'copy includes local rules only');
  if (originalClipboard) Object.defineProperty(navigator, 'clipboard', originalClipboard); else delete navigator.clipboard;
  $('#inherit-defaults').click(); await tick(); await click('[data-action="save-editor"]');
  assert($('.connection-meta').textContent.includes('不继承全局') && $('.connection-meta').textContent.includes('生效 2 条'), 'inheritance toggle affects only this pair');
  await click('[data-action="edit-local"][data-profile="server"]');
  await click('[data-action="toggle-import"]'); input('#paste-text', copied); await click('[data-action="preview-import"]');
  assert($('.import-preview').textContent.includes('2 条规则'), 'paste shows validated import preview');
  await click('[data-action="merge-import"]');
  assert(countEditable() === 2, 'import merges into local draft');
  await click('[data-action="save-editor"]');
  assert(document.querySelectorAll('.connection-meta')[1].textContent.includes('2 条本地'), 'imported rules save to the other SSH');
  await click('[data-action="edit-local"][data-profile="router"]');
  await click('[data-action="clear-rules"]'); await click('#dialog-actions [value="clear"]');
  assert(countEditable() === 0 && !$('#inherit-defaults').checked, 'clear only affects local draft and preserves inheritance choice');
  await click('[data-action="close-editor"]'); await click('#dialog-actions [value="discard"]');
  await click('[data-page="service"]'); input('#http-port', '4242'); $('#port-form').requestSubmit(); await tick();
  assert($('.service-status').textContent.includes(':4242/mcp'), 'service preview updates connection address');
  await click('[data-action="toggle-service"]'); assert($('#header-status').textContent.includes('已停止'), 'service state remains consistent in header');
  await click('[data-page="ssh"]'); $('#ssh-router').click(); await tick();
  assert($('#mode-router').disabled, 'disabled SSH cannot change its mode');
  await setScenario('empty'); assert(!!$('[data-action="add-client"]') && !$('.client-details'), 'empty state offers an add action');
  await click('[data-action="add-client"]'); await click('#dialog-actions [value="cancel"]');
  assert(!$('#action-dialog').open, 'empty client dialog can be canceled without validation');
  await click('[data-action="add-client"]'); input('#client-name-input', '测试客户端'); await click('#dialog-actions [value="save"]');
  assert($('.client-title h2').textContent === '测试客户端', 'new client is selected after creation');
  await setScenario('limit'); await click('[data-action="fill-global"]');
  assert(countEditable() === 128 && $('#rule-error').textContent.includes('128'), 'over-limit fill leaves all 128 draft rules intact');
  await click('[data-action="close-editor"]'); await click('[data-page="clients"]');
  assert($('.connection-meta').textContent.includes('生效 130 条'), 'effective count supports two independent 128-rule sets');
  await setScenario('normal'); await click('[data-action="edit-local"][data-profile="router"]');
  input('#rule-text', 'pwd'); await click('[data-action="edit-rule"][data-index="0"]');
  assert($('#action-dialog').open, 'switching rules protects pending command input');
  await click('#dialog-actions [value="cancel"]');
  assert($('#rule-text').value === 'pwd', 'canceling rule switch retains input');
  await click('[data-action="edit-rule"][data-index="0"]'); await click('#dialog-actions [value="apply"]');
  assert(countEditable() === 3 && $('#rule-text').value === 'docker ps', 'rule switch can add pending input before switching');
  await click('[data-action="toggle-import"]'); input('#paste-text', CommandSetPreview.exportSet([{kind: 'family', text: 'whoami'}]));
  await click('[data-action="preview-import"]'); await click('[data-action="replace-import"]'); await click('#dialog-actions [value="replace"]');
  assert($('#rule-text').value === '' && countEditable() === 1, 'replacement clears stale row edit state');
  await click('[data-action="save-editor"]'); await click('[data-action="edit-local"][data-profile="router"]');
  assert(countEditable() === 1 && $('.rule-list code').textContent === 'whoami', 'saving imported replacement never overwrites it with previous row input');
  assert(!document.documentElement.scrollWidth || document.documentElement.scrollWidth <= innerWidth, 'no horizontal page overflow');
  return {passed: checks.length, checks};
}
